11: @MainActor
12: final class AppState: ObservableObject {
13:     enum Page { case loading, auth, platforms, catalog }
14: 
15:     @Published var page: Page = .loading
16:     @Published var token: String = ""
17:     @Published var username: String = ""
18:     @Published var selectedPlatforms: [String] = []
19:     @Published var selectedLanguages: [String] = []
20:     @Published var watchedIds: Set<String> = []
21:     @Published var watchlistIds: Set<String> = []
22:     @Published var selectedThemeId: String = AppTheme.defaultTheme.id
23: 
24:     private let tokenKey      = "mk_token"
25:     private let usernameKey   = "mk_username"
26:     private let platformsKey  = "mk_platforms"
27:     private let languagesKey  = "mk_languages"
28:     private let watchedKey    = "mk_watched_ids"
29:     private let watchlistKey  = "mk_watchlist_ids"
30:     private let themeKey      = "mk_theme_id"
31:     private let defaults: UserDefaults
32: 
33:     init(userDefaults: UserDefaults = .standard) {
34:         defaults = userDefaults
35:         token    = defaults.string(forKey: tokenKey)?.trimmingCharacters(in: .whitespaces) ?? ""
36:         username = defaults.string(forKey: usernameKey) ?? ""
37:         selectedPlatforms = defaults.stringArray(forKey: platformsKey) ?? []
38:         selectedLanguages = defaults.stringArray(forKey: languagesKey) ?? []
39:         watchedIds  = Set(defaults.stringArray(forKey: watchedKey) ?? [])
40:         watchlistIds = Set(defaults.stringArray(forKey: watchlistKey) ?? [])
41:         let theme = AppTheme.theme(with: defaults.string(forKey: themeKey) ?? AppTheme.defaultTheme.id)
42:         selectedThemeId = theme.id
43:         ThemeManager.shared.applyTheme(theme)
44:         page = token.isEmpty ? .auth : .catalog
45:     }
46: 
47:     func saveSession(token: String, username: String, isNewUser: Bool = false) {
48:         self.token    = token.trimmingCharacters(in: .whitespaces)
49:         self.username = username
50:         defaults.set(self.token, forKey: tokenKey)
51:         defaults.set(username,   forKey: usernameKey)
52:         page = isNewUser ? .platforms : .catalog
53:     }
54: 
55:     func savePlatforms(_ platforms: [String]) {
56:         selectedPlatforms = platforms
57:         defaults.set(platforms, forKey: platformsKey)
58:     }
59: 
60:     func saveLanguages(_ languages: [String]) {
61:         selectedLanguages = languages
62:         defaults.set(languages, forKey: languagesKey)
63:     }
64: 
65:     func updateToken(_ newToken: String) {
66:         token = newToken.trimmingCharacters(in: .whitespaces)
67:         defaults.set(token, forKey: tokenKey)
68:     }
69: 
70:     func updateUsername(_ newUsername: String) {
71:         username = newUsername
72:         defaults.set(username, forKey: usernameKey)
73:     }
74: 
75:     func setWatched(_ id: String, watched: Bool) {
76:         if watched { watchedIds.insert(id) } else { watchedIds.remove(id) }
77:         defaults.set(Array(watchedIds), forKey: watchedKey)
78:     }
79: 
80:     func replaceWatchedIds(_ ids: [String]) {
81:         watchedIds = Set(ids)
82:         defaults.set(ids, forKey: watchedKey)
83:     }
84: 
85:     func setWatchlisted(_ id: String, on: Bool) {
86:         if on { watchlistIds.insert(id) } else { watchlistIds.remove(id) }
87:         defaults.set(Array(watchlistIds), forKey: watchlistKey)
88:     }
89: 
90:     func replaceWatchlistIds(_ ids: [String]) {
91:         watchlistIds = Set(ids)
92:         defaults.set(ids, forKey: watchlistKey)
93:     }
94: 
95:     func saveTheme(_ id: String) {
96:         let theme = AppTheme.theme(with: id)
97:         selectedThemeId = theme.id
98:         defaults.set(theme.id, forKey: themeKey)
99:         ThemeManager.shared.applyTheme(theme)
100:     }
101: 
102:     func logout() {
103:         token = ""; username = ""; selectedPlatforms = []; selectedLanguages = []
104:         watchedIds = []; watchlistIds = []
105:         defaults.removeObject(forKey: tokenKey)
106:         defaults.removeObject(forKey: usernameKey)
107:         defaults.removeObject(forKey: platformsKey)
108:         defaults.removeObject(forKey: languagesKey)
109:         defaults.removeObject(forKey: watchedKey)
110:         defaults.removeObject(forKey: watchlistKey)
111:         page = .auth
112:     }
113: }
