340:     func authenticate() async {
341:         let trimmedUser = username.trimmingCharacters(in: .whitespaces)
342:         guard !trimmedUser.isEmpty, !password.isEmpty else {
343:             errorMsg = "Please fill in both fields."; return
344:         }
345:         isLoading = true; clearMessages()
346:         do {
347:             var body: [String: Any] = ["username": trimmedUser, "password": password]
348:             if mode == .register, !registerEmail.isEmpty { body["email"] = registerEmail }
349:             let resp: AuthResponse = try await APIService.shared.post(
350:                 mode == .login ? "/login" : "/register", body: body
351:             )
352:             if let t = resp.token {
353:                 app.saveSession(token: t, username: trimmedUser, isNewUser: mode == .register)
354:             } else {
355:                 errorMsg = resp.error ?? "Authentication failed."
356:             }
357:         } catch {
358:             errorMsg = (error as? APIError)?.errorDescription ?? "Network error."
359:         }
360:         isLoading = false
361:     }
