365:     func sendResetCode() async {
366:         guard !resetEmail.isEmpty else { errorMsg = "Enter your email address."; return }
367:         isLoading = true; clearMessages()
368:         do {
369:             let resp: ForgotPasswordResponse = try await APIService.shared.post(
370:                 "/auth/forgot-password", body: ["email": resetEmail]
371:             )
372:             _ = resp
373:             successMsg = "Code sent! Check your email."
374:             withAnimation { resetStep = .enterCode }
375:         } catch {
376:             // Backend always returns 200 so any error is a network issue
377:             errorMsg = (error as? APIError)?.errorDescription ?? "Network error."
378:         }
379:         isLoading = false
380:     }
381: 
382:     func submitReset() async {
383:         guard !resetCode.isEmpty, !resetNewPass.isEmpty else {
384:             errorMsg = "Enter both the code and a new password."; return
385:         }
386:         isLoading = true; clearMessages()
387:         do {
388:             let resp: ForgotPasswordResponse = try await APIService.shared.post(
389:                 "/auth/reset-password",
390:                 body: ["email": resetEmail, "code": resetCode, "newPassword": resetNewPass]
391:             )
392:             if resp.success == true {
393:                 successMsg = "Password reset! Sign in with your new password."
394:                 withAnimation { resetStep = .none; mode = .login }
395:                 resetCode = ""; resetNewPass = ""
396:             } else {
397:                 errorMsg = resp.error ?? "Invalid code or it has expired."
398:             }
399:         } catch {
400:             errorMsg = (error as? APIError)?.errorDescription ?? "Network error."
401:         }
402:         isLoading = false
